use sqlx::{PgPool, FromRow};
use chrono::{DateTime, Utc};

#[derive(Debug, FromRow)]
pub struct UserRecord {
    pub id: i64,
    pub username: String,
    pub email: String,
    pub is_active: bool,
    pub created_at: DateTime<Utc>,
}

pub async fn find_user_by_email(pool: &PgPool, email: &str) -> Result<Option<UserRecord>, sqlx::Error> {
    // ماكرو query_as! يفحص الاستعلام في الـ Compile-time ويرجع UserRecord مباشرة:
    let user = sqlx::query_as!(
        UserRecord,
        r#"
        SELECT id, username, email, is_active, created_at
        FROM users
        WHERE email = $1
        "#,
        email
    )
    .fetch_optional(pool)
    .await?;

    Ok(user)
}

pub async fn create_user(
    pool: &PgPool,
    username: &str,
    email: &str,
) -> Result<i64, sqlx::Error> {
    let record = sqlx::query!(
        r#"
        INSERT INTO users (username, email, is_active, created_at)
        VALUES ($1, $2, true, NOW())
        RETURNING id
        "#,
        username,
        email
    )
    .fetch_one(pool)
    .await?;

    Ok(record.id)
}

